INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 15, 'theory', 'Quiz: HTML: forms and accessibility');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 0, 'What happens to a form field that has no name attribute?', '["It goes into the request with an empty name", "The browser takes the name from the id attribute", "It does not get into the request, no matter how much the person typed", "The form is not sent at all"]', 2, 'The request carries "name=value" pairs that the browser builds from name; id is for links, styles and scripts and does not go into the request.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 1, 'Why do we need a label linked to a field through for or by wrapping?', '["So that the field value gets into the request", "A click on the label puts the cursor in the field, and a screen reader reads the name when entering the field", "To make the field required", "So that the browser fills in a saved password"]', 1, 'A label enlarges the target for tapping and gives assistive technology the name of the field. A placeholder does not replace it: it disappears when you type and is not always announced.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 2, 'What will a button without a type attribute do inside a form?', '["Nothing until a script is added", "Reset the fields to their initial values", "Behave like type=\"button\"", "Submit the form, like type=\"submit\""]', 3, 'The default type of a button is submit, so any helper button inside a form (show the password, add a row) is marked type="button".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 3, 'How does readonly differ from disabled?', '["A readonly field gets focus and goes into the request but cannot be edited; a disabled field gets no focus and is not sent", "They do not differ at all", "A disabled field goes into the request, a readonly one does not", "Readonly hides the field, disabled shows it greyed out"]', 0, 'Disabled turns the field off completely; readonly leaves it visible, selectable and submitted, only the value cannot be edited.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 4, 'What is the right way to report an error in a form field?', '["Highlight the field with a red border", "Show an alert pop-up and clear the field", "Write text next to the field, link it through aria-describedby, and set aria-invalid=\"true\"", "Block the submit button without any explanation"]', 2, 'Some people cannot tell colors apart, and a screen reader cannot hear them. Text says what happened and how to fix it, and the link through describedby and aria-invalid makes the error accessible.');
